class Eager {
  constructor(executor) {
    this.callbacks = [];
    executor((value) => {
      this.value = value;
      this.done = true;
      this.callbacks.forEach((callback) => callback(value));
    });
  }

  then(callback) {
    if (this.done) callback(this.value);
    else this.callbacks.push(callback);
  }
}

new Eager((resolve) => setTimeout(resolve, 10, "eager, later")).then((v) => console.log(v));
new Eager((resolve) => resolve("eager, now")).then((v) => console.log(v));
